const EMBEDDED_WEBP_B64 = "";

function packAppOnboarding() {
  for (const root of PACK_APP_CANDIDATES) {
    const ts = join(root, 'src', 'components', 'onboarding', 'globeFlightPaths.generated.ts');
    if (existsSync(ts)) {
      return join(root, 'src', 'components', 'onboarding');
    }
  }
  return null;
}

function writeDest(tsSource, webpBuf) {
  mkdirSync(DEST_DIR, { recursive: true });
  writeFileSync(DEST_TS, tsSource);
  writeFileSync(DEST_WEBP, webpBuf);
}

const appDir = packAppOnboarding();
if (appDir) {
  mkdirSync(DEST_DIR, { recursive: true });
  copyFileSync(join(appDir, 'globeFlightPaths.generated.ts'), DEST_TS);
  const poster = join(appDir, 'globe-poster.webp');
  if (existsSync(poster)) {
    copyFileSync(poster, DEST_WEBP);
  } else {
    writeFileSync(DEST_WEBP, Buffer.from(EMBEDDED_WEBP_B64, 'base64'));
  }
} else {
  writeDest(EMBEDDED_TS, Buffer.from(EMBEDDED_WEBP_B64, 'base64'));
}

process.stdout.write('regen-web-onboarding-is-the-app-onboarding wrote globe assets\n');
